import{_ as i,o as t,c as a,ae as o}from"./chunks/framework.1Lna8NcP.js";const h=JSON.parse('{"title":"ADR-009: Optional Plaid + Sheets Integration with Canonical Multi-Source Ingest","description":"","frontmatter":{},"headers":[],"relativePath":"adr/009-optional-plaid-and-sheets-integration.md","filePath":"adr/009-optional-plaid-and-sheets-integration.md"}'),l={name:"adr/009-optional-plaid-and-sheets-integration.md"};function n(r,e,s,c,d,u){return t(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="adr-009-optional-plaid-sheets-integration-with-canonical-multi-source-ingest" tabindex="-1">ADR-009: Optional Plaid + Sheets Integration with Canonical Multi-Source Ingest <a class="header-anchor" href="#adr-009-optional-plaid-sheets-integration-with-canonical-multi-source-ingest" aria-label="Permalink to &quot;ADR-009: Optional Plaid + Sheets Integration with Canonical Multi-Source Ingest&quot;">​</a></h1><ul><li>Date: 2026-04-14</li><li>Status: Accepted</li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>Libertas is local-first and must keep CSV/Excel/manual workflows fully first-class. We need expanded source coverage for household cashflow and liabilities without introducing blocking cloud coupling.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><ol><li>Add optional integrations under Settings only:</li></ol><ul><li>Plaid link/exchange/sync/relink/disconnect</li><li>Google Sheets CSV-export feeds (no Google OAuth)</li></ul><ol start="2"><li>Route all sources through one canonical ingest precedence model:</li></ol><ul><li><code>plaid external_id</code> &gt; <code>csv/excel import hash</code> &gt; <code>sheets row id</code> &gt; <code>manual</code></li></ul><ol start="3"><li><p>Persist provenance + conflict metadata on accounts and transactions for debugging.</p></li><li><p>Encrypt provider secrets at rest locally.</p></li><li><p>Default sync cadence:</p></li></ol><ul><li>User-triggered manual sync anytime</li><li>Daily background sync loop</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><p>Positive:</p><ul><li>Better source coverage while preserving local-first usage</li><li>Deterministic dedup and clearer merge behavior</li><li>Optionality preserved: users ignoring integrations retain existing UX</li></ul><p>Trade-offs:</p><ul><li>Plaid connectivity depends on external credentials/network</li><li>Sheets feeds depend on stable CSV URLs and column mapping quality</li></ul><h2 id="out-of-scope" tabindex="-1">Out of Scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of Scope&quot;">​</a></h2><ul><li>PDF parsing/OCR (explicitly deferred)</li><li>Google OAuth Sheets API integration</li><li>Mandatory onboarding connect flows</li></ul>',18)])])}const g=i(l,[["render",n]]);export{h as __pageData,g as default};
